    // Helper function to check if a number is a power of two
    fn is_power_of_two(x: i32) -> bool {
        x > 0 && (x & (x - 1)) == 0
    }

    // Helper function to determine "limited-prime" as defined:
    // p ≤ 1 => not prime
    // p = 2 => prime
    // even p > 2 => not prime
    // odd p > 2 => prime
    fn is_limited_prime(p: i32) -> bool {
        if p <= 1 {
            false
        } else if p == 2 {
            true
        } else if p % 2 == 0 {
            false
        } else {
            true
        }
    }

